 sheet.save(out/'bloom-onde-cromatiche.png');(out/'intermediates.json').write_text(json.dumps(data['morphs'],indent=2));b.close();print('Continuous flower-to-hedgehog intermediates and final Bloom example: PASS '+json.dumps(data['morphs']),flush=True)
